const AWS = require('aws-sdk');
const https = require('https');
const url = require('url');

// Helper function to respond to CloudFormation
async function sendResponse(event, context, responseStatus, responseData, physicalResourceId) {
  const responseBody = JSON.stringify({
    Status: responseStatus,
    Reason: responseData.reason || "See the details in CloudWatch Log Stream: " + context.logStreamName,
    PhysicalResourceId: physicalResourceId || context.logStreamName,
    StackId: event.StackId,
    RequestId: event.RequestId,
    LogicalResourceId: event.LogicalResourceId,
    NoEcho: false,
    Data: responseData
  });

  console.log("Response body: ", responseBody);

  const parsedUrl = url.parse(event.ResponseURL);
  const options = {
    hostname: parsedUrl.hostname,
    port: 443,
    path: parsedUrl.path,
    method: "PUT",
    headers: {
      "content-type": "",
      "content-length": responseBody.length
    }
  };

  return new Promise((resolve, reject) => {
    const request = https.request(options, function(response) {
      console.log("Status code: " + response.statusCode);
      console.log("Status message: " + response.statusMessage);
      resolve();
    });

    request.on("error", function(error) {
      console.log("send() error: " + error);
      reject(error);
    });

    request.write(responseBody);
    request.end();
  });
}

exports.handler = async (event, context) => {
  console.log("REQUEST RECEIVED: " + JSON.stringify(event));

  // For Delete events, immediately send a success response
  if (event.RequestType === "Delete") {
    // Note: We don't actually delete the WorkMail organization automatically
    // as it might contain important emails. Manual cleanup is required.
    console.log("DELETE request - NOT removing WorkMail organization - manual cleanup required");

    await sendResponse(event, context, "SUCCESS", {
      message: "Manual deletion required for WorkMail organization to preserve data"
    });
    return;
  }

  try {
    // Setup WorkMail SDK with the specified region
    const workmail = new AWS.WorkMail({ 
      region: event.ResourceProperties.Region || process.env.AWS_REGION
    });

    const organizationName = event.ResourceProperties.OrganizationName;

    // For Create request, try to create the organization
    if (event.RequestType === "Create") {
      // Check if organization already exists with the same name
      const listOrgsResult = await workmail.listOrganizations({}).promise();
      const existingOrg = listOrgsResult.OrganizationSummaries.find(
        org => org.Alias === organizationName
      );

      let organizationId;

      if (existingOrg) {
        console.log("Organization already exists:", existingOrg);
        organizationId = existingOrg.OrganizationId;
      } else {
        // Create new organization
        console.log("Creating new WorkMail organization");
        const createResult = await workmail.createOrganization({
          Alias: organizationName,
          DirectoryId: 'NONE', // Create a new directory
          Domains: [] // No domains initially, will be added manually
        }).promise();

        organizationId = createResult.OrganizationId;
        console.log("Created organization:", organizationId);

        // Wait for organization to become active
        let orgStatus;
        let retries = 0;
        const maxRetries = 30;

        do {
          retries++;
          await new Promise(resolve => setTimeout(resolve, 5000)); // Wait 5 seconds

          const describeResult = await workmail.describeOrganization({
            OrganizationId: organizationId
          }).promise();

          orgStatus = describeResult.State;
          console.log(`Organization status (${retries}/${maxRetries}): ${orgStatus}`);
        } while (orgStatus !== 'ACTIVE' && retries < maxRetries);

        if (orgStatus !== 'ACTIVE') {
          throw new Error(`Organization not active after ${maxRetries} retries`);
        }
      }

      // Send response with the organization ID
      await sendResponse(event, context, "SUCCESS", {
        organizationId: organizationId,
        alias: organizationName,
        region: event.ResourceProperties.Region || process.env.AWS_REGION
      }, organizationId);

    } else if (event.RequestType === "Update") {
      // For update requests, just return success with the existing organization ID
      // WorkMail organizations can't be easily updated via API
      await sendResponse(event, context, "SUCCESS", {
        organizationId: event.PhysicalResourceId,
        message: "WorkMail organization updates require manual configuration"
      }, event.PhysicalResourceId);
    }
  } catch (error) {
    console.error("Error:", error);
    await sendResponse(event, context, "FAILED", {
      reason: "Error: " + error.message,
      stackTrace: error.stack
    });
  }
}
